import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"FD Cal interest day-count convention","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/finance/INTEREST-DAY-COUNT.html"}],["meta",{"property":"og:title","content":"FD Cal interest day-count convention | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/finance/INTEREST-DAY-COUNT.html"}],["meta",{"name":"twitter:title","content":"FD Cal interest day-count convention | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"finance/INTEREST-DAY-COUNT.md","filePath":"finance/INTEREST-DAY-COUNT.md","lastUpdated":1794227887000}`),a={name:`finance/INTEREST-DAY-COUNT.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="fd-cal-interest-day-count-convention" tabindex="-1">FD Cal interest day-count convention <a class="header-anchor" href="#fd-cal-interest-day-count-convention" aria-label="Permalink to “FD Cal interest day-count convention”">​</a></h1><p><strong>Reviewed:</strong> 9 November 2026<br><strong>Status:</strong> Current implementation retained by owner decision.<br><strong>Scope:</strong> This note explains the annual-rate denominator used by FD Cal. It is not a statement that every bank uses the same convention.</p><h2 id="calculation" tabindex="-1">Calculation <a class="header-anchor" href="#calculation" aria-label="Permalink to “Calculation”">​</a></h2><p>FD Cal measures the actual number of elapsed calendar days between the accrual start and end dates. When the “Actual leap-year day count” option is enabled, it selects one annual denominator from the <strong>calendar year in which accrual starts</strong>:</p><ul><li>366 days if the start year is a leap year.</li><li>365 days if the start year is not a leap year.</li></ul><p>That selected denominator is applied to the entire accrual interval. An interval crossing into another calendar year is not split into separate yearly segments.</p><p>For simple interest:</p><p><code>interest = principal × (annual_rate / 100) × elapsed_days / year_base_days</code></p><p>For compound interest, the same selected denominator is used as the daily compounding base.</p><p>If leap-year handling is disabled, the denominator is 365.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p>An FD opened in a non-leap year uses 365 as its denominator even if its tenor crosses into a leap year. An FD opened in a leap year uses 366 for the complete interval, even if it matures in the following non-leap year.</p><p>This is a start-year denominator convention. It is not calendar-segmented Actual/Actual.</p><h2 id="why-it-remains-unchanged" tabindex="-1">Why it remains unchanged <a class="header-anchor" href="#why-it-remains-unchanged" aria-label="Permalink to “Why it remains unchanged”">​</a></h2><p>The owner confirmed that FD Cal should use the year associated with the accrual start/rate assumption, and that the current relative elapsed-day approach is intentional. No reviewed public bank product page established a universal Sri Lankan bank day-count basis that would justify replacing it.</p><p>Public product references reviewed:</p><ul><li><a href="https://www.hnbfinance.lk/fixed-deposits/" target="_blank" rel="noreferrer">HNB Finance — Fixed Deposits</a> — publishes tenor and monthly/maturity payout choices.</li><li><a href="https://www.nsb.lk/product/ordinary-term/fixed-deposit/" target="_blank" rel="noreferrer">National Savings Bank — Fixed Deposit</a> — publishes available tenors and monthly/maturity interest payout.</li><li><a href="https://www.combank.lk/downloads/file/206/fixed-deposits" target="_blank" rel="noreferrer">Commercial Bank — Fixed Deposit Key Facts Document</a> — publishes product terms and payout choices.</li></ul><p>These references do not specify enough detail to assert that their underlying calculations match FD Cal&#39;s start-year denominator. Users should verify the applicable day-count, compounding, rounding and early-withdrawal terms with the relevant bank.</p><h2 id="change-control" tabindex="-1">Change control <a class="header-anchor" href="#change-control" aria-label="Permalink to “Change control”">​</a></h2><p>Do not silently switch to Actual/Actual calendar-year segmentation, Actual/365, Actual/366, or a bank-specific convention. Any change requires:</p><ol><li>An authoritative bank/product source identifying the convention.</li><li>Expected-value fixtures for leap-year and cross-year periods.</li><li>Before/after results for simple and compound interest.</li><li>A separate owner-approved financial-model change.</li></ol>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};